  (
    12,
    1,
    1,
    NULL,
    NULL,
    NULL,
    NULL,
    '2026-04-02 07:34:57',
    '2026-04-02 07:34:57',
    'Default Salary Slip Template',
    'salary-slip',
    '<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n  <title>Salary Slip</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;600&display=swap\" rel=\"stylesheet\"/>\n  <style>\n    :root { --text:#111; --text-muted:#555; --border-heavy:2px solid #111; --border-light:1px solid #ccc; --border-dashed:1px dashed #999; --accent:#1a1a1a; --bg:#fff; --row-alt:#f9f9f9; --font-body:\'IBM Plex Sans\',sans-serif; --font-mono:\'IBM Plex Mono\',monospace; }\n    *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\n    html,body{width:21cm;height:29.7cm;margin:0 auto;font-family:var(--font-body);color:var(--text);background:#e8e8e8;font-size:22px;line-height:1.5}\n    .page-wrap{width:21cm;height:29.7cm;overflow:hidden;background:var(--bg);box-shadow:0 4px 32px rgba(0,0,0,0.18)}\n    .doc{width:21cm;height:29.7cm;padding:10px;overflow:hidden}\n    .header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:28px;padding-bottom:24px;border-bottom:var(--border-heavy)}\n    .logo{height:140px;object-fit:contain}\n    .company{text-align:right;max-width:320px}\n    .company .name{font-size:32px;font-weight:700;letter-spacing:-0.02em;margin-bottom:6px;color:var(--accent)}\n    .company p{font-size:17px;color:var(--text-muted);line-height:1.6}\n    .titlebar{display:flex;align-items:center;gap:16px;margin-bottom:28px}\n    .titlebar .line{flex:1;height:2px;background:var(--text)}\n    .titlebar .title{font-size:20px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;white-space:nowrap;color:var(--accent)}\n    .info{display:grid;grid-template-columns:1fr 1fr auto;gap:24px;margin-bottom:28px;padding:20px 24px;border:var(--border-light);background:#fafafa}\n    .kv-table{display:table;width:100%}\n    .kv-row{display:table-row}\n    .kv-label{display:table-cell;font-weight:600;font-size:15px;padding:3px 10px 3px 0;white-space:nowrap;vertical-align:top;color:var(--text)}\n    .kv-sep{display:table-cell;padding:3px 10px 3px 0;color:var(--text-muted);vertical-align:top}\n    .kv-val{display:table-cell;font-size:15px;vertical-align:top;text-transform:uppercase;color:var(--text);font-weight:500}\n    .info-right{display:flex;flex-direction:column;align-items:center;justify-content:flex-start}\n    .qr-box{width:80px;height:80px}\n    .qr-box img{width:100%;height:100%}\n    .pay-section{display:grid;grid-template-columns:1fr 1fr;gap:0;border:var(--border-heavy);margin-bottom:24px;font-size:15px}\n    .pay-col{display:flex;flex-direction:column}\n    .pay-col:first-child{border-right:var(--border-heavy)}\n    .pay-col-header{padding:10px 12px;font-size:14px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:var(--accent);border-bottom:var(--border-heavy);display:flex;justify-content:space-between}\n    .pay-row{display:flex;justify-content:space-between;padding:8px 12px;border-bottom:var(--border-dashed)}\n    .pay-row:nth-child(even){background:var(--row-alt)}\n    .pay-row .pay-label{color:var(--text);font-weight:500}\n    .pay-row .pay-val{font-family:var(--font-mono);font-weight:600}\n    .pay-col-total{display:flex;justify-content:space-between;padding:10px 12px;border-top:var(--border-heavy);margin-top:auto;font-weight:700;font-size:15px}\n    .pay-col-total .pay-val{font-family:var(--font-mono)}\n    .bottom-section{display:flex;justify-content:space-between;gap:32px;margin-bottom:36px}\n    .bottom-left{flex:1;font-size:15px;display:flex;flex-direction:column;gap:16px}\n    .meta-row{display:flex;gap:40px;flex-wrap:wrap}\n    .meta-item .lbl{font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:0.04em;color:var(--text-muted);display:block;margin-bottom:2px}\n    .meta-item .val{font-size:15px;font-weight:600}\n    .amount-words .lbl,.remarks .lbl{font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:0.04em;color:var(--text-muted);display:block;margin-bottom:4px}\n    .amount-words .val{font-size:14px;font-weight:600;text-transform:uppercase;color:var(--accent);font-family:var(--font-mono)}\n    .remarks .val{font-size:14px;color:var(--text);line-height:1.6}\n    .summary{width:260px;flex-shrink:0;font-size:15px}\n    .summary-row{display:flex;justify-content:space-between;align-items:flex-start;padding:8px 0;border-bottom:var(--border-dashed);gap:12px}\n    .summary-row:last-child{border-bottom:var(--border-heavy);padding-top:10px;padding-bottom:10px;border-top:var(--border-heavy);margin-top:4px}\n    .s-label{font-weight:600;color:var(--text);font-size:15px}\n    .s-val{font-family:var(--font-mono);font-weight:600;font-size:15px;white-space:nowrap}\n    .summary-row:last-child .s-label,.summary-row:last-child .s-val{font-size:18px;font-weight:700}\n    .footer-prepared{display:flex;align-items:center;gap:10px;padding-top:16px;border-top:var(--border-heavy);font-size:15px}\n    .footer-prepared .lbl{font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted)}\n    .footer-prepared .val{font-weight:600}\n    .footer-note{margin-left:auto;font-size:13px;color:var(--text-muted);font-style:italic}\n    @media print { @page{size:21cm 29.7cm;margin:0} html,body{background:#fff;width:21cm;height:29.7cm} .page-wrap{box-shadow:none;width:21cm;height:29.7cm} *{-webkit-print-color-adjust:exact;print-color-adjust:exact} }\n  </style>\n</head>\n<body>\n  <div class=\"page-wrap\">\n    <div class=\"doc\">\n      <div class=\"header\">\n        <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\"/>\n        <div class=\"company\">\n          <div class=\"name\">{{company.name}}</div>\n          <p>{{company.address}}</p>\n          <p>{{company.address2}}</p>\n          <p>Contact No: {{company.telephone}}</p>\n          <p>Email: {{company.email}}</p>\n        </div>\n      </div>\n      <div class=\"titlebar\"><div class=\"line\"></div><div class=\"title\">Salary Slip</div><div class=\"line\"></div></div>\n      <div class=\"info\">\n        <div class=\"info-left\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\"><div class=\"kv-label\">Employee Name</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.name}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Employee ID</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.code}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Department</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.department}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Designation</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.job_title}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Date of Joining</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{formatDate employee.joining_date}}</div></div>\n          </div>\n        </div>\n        <div class=\"info-mid\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\"><div class=\"kv-label\">Pay Period</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{payslip.period_name}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Pay Date</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{formatDate payslip.paid_at}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Bank Account</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.bank_account_no}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">Bank Name</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.bank_name}}</div></div>\n            <div class=\"kv-row\"><div class=\"kv-label\">PAN / TIN</div><div class=\"kv-sep\">:</div><div class=\"kv-val\">{{employee.tin}}</div></div>\n          </div>\n        </div>\n        <div class=\"info-right\"><div class=\"qr-box\"><img src=\"{{payslip.qr_code}}\" alt=\"QR\"/></div></div>\n      </div>\n      <div class=\"pay-section\">\n        <div class=\"pay-col\">\n          <div class=\"pay-col-header\"><span>Earnings</span><span>Amount</span></div>\n          {{#each payslip.rows}}{{#if earning_label}}<div class=\"pay-row\"><span class=\"pay-label\">{{earning_label}}</span><span class=\"pay-val\">{{earning_amount}}</span></div>{{/if}}{{/each}}\n          <div class=\"pay-col-total\"><span>Total Earnings</span><span class=\"pay-val\">{{payslip.gross_pay}}</span></div>\n        </div>\n        <div class=\"pay-col\">\n          <div class=\"pay-col-header\"><span>Deductions</span><span>Amount</span></div>\n          {{#each payslip.rows}}{{#if deduction_label}}<div class=\"pay-row\"><span class=\"pay-label\">{{deduction_label}}</span><span class=\"pay-val\">{{deduction_amount}}</span></div>{{/if}}{{/each}}\n          <div class=\"pay-col-total\"><span>Total Deductions</span><span class=\"pay-val\">{{payslip.deductions}}</span></div>\n        </div>\n      </div>\n      <div class=\"bottom-section\">\n        <div class=\"bottom-left\">\n          <div class=\"meta-row\">\n            <div class=\"meta-item\"><span class=\"lbl\">Working Days</span><span class=\"val\">{{payslip.working_days}}</span></div>\n            <div class=\"meta-item\"><span class=\"lbl\">Days Present</span><span class=\"val\">{{payslip.days_present}}</span></div>\n            <div class=\"meta-item\"><span class=\"lbl\">Leave Taken</span><span class=\"val\">{{payslip.leave_taken}}</span></div>\n          </div>\n          <div class=\"amount-words\"><span class=\"lbl\">Net Pay in Words</span><span class=\"val\">{{payslip.net_in_words}}</span></div>\n          <div class=\"remarks\"><span class=\"lbl\">Remarks</span><span class=\"val\">{{payslip.remarks}}</span></div>\n        </div>\n        <div class=\"summary\">\n          <div class=\"summary-row\"><span class=\"s-label\">Gross Earnings</span><span class=\"s-val\">{{payslip.gross_pay}}</span></div>\n          <div class=\"summary-row\"><span class=\"s-label\">Total Deductions</span><span class=\"s-val\">{{payslip.deductions}}</span></div>\n          <div class=\"summary-row\"><span class=\"s-label\">Net Pay</span><span class=\"s-val\">{{payslip.net_salary}}</span></div>\n        </div>\n      </div>\n      <div class=\"footer-prepared\"><span class=\"lbl\">Prepared By :</span><span class=\"val\">{{prepared_by}}</span><span class=\"footer-note\">This is a computer-generated document and does not require a signature.</span></div>\n    </div>\n  </div>\n</body>\n</html>',
    NULL,
    NULL,
    NULL,
    1,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL
  );

