    'invoice',
    '<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Sales Invoice</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;600&amp;display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --text: #111111;\n      --text-muted: #555555;\n      --border-heavy: 2px solid #111111;\n      --border-light: 1px solid #cccccc;\n      --border-dashed: 1px dashed #999999;\n      --accent: #1a1a1a;\n      --bg: #ffffff;\n      --row-alt: #f9f9f9;\n      --font-body: \'IBM Plex Sans\', sans-serif;\n      --font-mono: \'IBM Plex Mono\', monospace;\n    }\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    html, body {\n      width: 21cm;\n      margin: 0 auto;\n      font-family: var(--font-body);\n      color: var(--text);\n      background: #e8e8e8;\n      font-size: 11px;\n      line-height: 1.4;\n    }\n\n    .page-wrap {\n      width: 21cm;\n      background: var(--bg);\n      box-shadow: 0 4px 32px rgba(0,0,0,0.18);\n    }\n\n    .doc {\n      width: 100%;\n      padding: 1cm;\n    }\n\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin-bottom: 28px;\n      padding-bottom: 24px;\n      border-bottom: var(--border-heavy);\n    }\n\n    .logo {\n      height: 140px;\n      object-fit: contain;\n    }\n\n    .company {\n      text-align: right;\n      max-width: 320px;\n    }\n\n    .company .name {\n      font-size: 22px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      margin-bottom: 6px;\n      color: var(--accent);\n    }\n\n    .company p {\n      font-size: 12px;\n      color: var(--text-muted);\n      line-height: 1.6;\n    }\n\n    .titlebar {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 28px;\n    }\n\n    .titlebar .line {\n      flex: 1;\n      height: 2px;\n      background: var(--text);\n    }\n\n    .titlebar .title {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n      white-space: nowrap;\n      color: var(--accent);\n    }\n\n    .info {\n      display: grid;\n      grid-template-columns: 1fr 1fr auto;\n      gap: 24px;\n      margin-bottom: 28px;\n      padding: 20px 24px;\n      border: var(--border-light);\n      background: #fafafa;\n    }\n\n    .kv-table { display: table; width: 100%; }\n    .kv-row { display: table-row; }\n\n    .kv-label {\n      display: table-cell;\n      font-weight: 600;\n      font-size: 11px;\n      padding: 3px 10px 3px 0;\n      white-space: nowrap;\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .kv-sep {\n      display: table-cell;\n      padding: 3px 10px 3px 0;\n      color: var(--text-muted);\n      vertical-align: top;\n    }\n\n    .kv-val {\n      display: table-cell;\n      font-size: 11px;\n      vertical-align: top;\n      text-transform: uppercase;\n      color: var(--text);\n      font-weight: 500;\n    }\n\n    .info-right {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: flex-start;\n    }\n\n    .items-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 11px;\n      margin-bottom: 12px;\n    }\n\n    .items-table thead th {\n      border-top: var(--border-heavy);\n      border-bottom: var(--border-heavy);\n      padding: 8px 6px;\n      font-size: 10px;\n      font-weight: 700;\n      letter-spacing: 0.02em;\n      text-transform: uppercase;\n      color: var(--accent);\n      background: #fff;\n      white-space: nowrap;\n    }\n\n    .items-table thead th.left { text-align: left; }\n    .items-table thead th.right { text-align: right; }\n    .items-table thead th.center { text-align: center; }\n\n    .items-table th:nth-child(1),\n    .items-table td:nth-child(1) { width: 45px; text-align: center; }\n\n    .items-table th:nth-child(2),\n    .items-table td:nth-child(2) { width: 90px; text-align: left; }\n\n    .items-table th:nth-child(3),\n    .items-table td:nth-child(3) { width: auto; text-align: left; }\n\n    .items-table th:nth-child(4),\n    .items-table td:nth-child(4) { width: 60px; text-align: right; }\n\n    .items-table th:nth-child(5),\n    .items-table td:nth-child(5) { width: 90px; text-align: right; }\n\n    .items-table th:nth-child(6),\n    .items-table td:nth-child(6) { width: 100px; text-align: right; }\n\n    .items-table tbody td {\n      padding: 8px 6px;\n      border-bottom: var(--border-dashed);\n      vertical-align: top;\n      color: var(--text);\n      overflow: hidden;\n      text-overflow: ellipsis;\n    }\n\n    .items-table tbody tr:nth-child(even) td { background: var(--row-alt); }\n    .items-table tbody tr:last-child td { border-bottom: var(--border-heavy); }\n\n    .items-table td.num {\n      font-family: var(--font-mono);\n      font-size: 11px;\n      white-space: nowrap;\n    }\n\n    .items-table td.center { text-align: center; }\n    .items-table td.sr { color: var(--text-muted); font-weight: 600; }\n\n    .bottom-section {\n      display: flex;\n      justify-content: space-between;\n      gap: 32px;\n    }\n\n    .bottom-left {\n      flex: 1;\n      font-size: 11px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n    }\n\n    .meta-row { display: flex; gap: 40px; }\n\n    .meta-item .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 2px;\n    }\n\n    .meta-item .val { font-size: 11px; font-weight: 600; }\n\n    .amount-words .lbl,\n    .remarks .lbl,\n    .terms .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 4px;\n    }\n\n    .amount-words .val {\n      font-size: 11px;\n      font-weight: 600;\n      text-transform: uppercase;\n      color: var(--accent);\n      font-family: var(--font-mono);\n    }\n\n    .remarks .val,\n    .terms .val {\n      font-size: 11px;\n      color: var(--text);\n      line-height: 1.6;\n    }\n\n    .summary {\n      width: 260px;\n      flex-shrink: 0;\n      font-size: 11px;\n    }\n\n    .summary-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      padding: 8px 0;\n      border-bottom: var(--border-dashed);\n      gap: 12px;\n    }\n\n    .summary-row.total-row {\n      border-bottom: var(--border-heavy);\n      border-top: var(--border-heavy);\n      padding-top: 10px;\n      padding-bottom: 10px;\n      margin-top: 4px;\n    }\n\n    .s-label { font-weight: 600; color: var(--text); font-size: 11px; }\n\n    .s-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      font-size: 11px;\n      white-space: nowrap;\n    }\n\n    .summary-row.total-row .s-label,\n    .summary-row.total-row .s-val {\n      font-size: 13px;\n      font-weight: 700;\n    }\n\n    .tax-component-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      padding: 4px 0;\n      border-bottom: var(--border-dashed);\n      gap: 12px;\n      font-size: 11px;\n    }\n\n    .tcr-label {\n      font-weight: 600;\n      color: var(--text);\n    }\n\n    .tcr-amount {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      white-space: nowrap;\n    }\n\n    .footer-prepared {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding-top: 16px;\n      border-top: var(--border-heavy);\n      font-size: 11px;\n    }\n\n    .footer-prepared .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: var(--text-muted);\n    }\n\n    .footer-prepared .val { font-weight: 600; }\n\n    @media print {\n      @page { size: 21cm 29.7cm; margin: 0; }\n      html, body { background: #fff; width: 21cm; height: auto; }\n      .page-wrap { box-shadow: none; width: 21cm; height: auto; }\n      .doc { width: 21cm; height: auto; }\n      * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n    }\n  </style>\n</head>\n<body>\n<div class=\"page-wrap\">\n  <div class=\"doc\">\n    <div class=\"header\">\n      <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\" />\n      <div class=\"company\">\n        <div class=\"name\">{{company.name}}</div>\n        <p>{{company.address}}</p>\n        <p>{{company.address2}}</p>\n        <p>Contact No: {{company.phone}}</p>\n        <p>Email: {{company.email}}</p>\n      </div>\n    </div>\n\n    <div class=\"titlebar\">\n      <div class=\"line\"></div>\n      <div class=\"title\">Sales Invoice</div>\n      <div class=\"line\"></div>\n    </div>\n\n    <div class=\"info\">\n      <div class=\"info-left\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Customer Name</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{customer.name}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Address</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{customer.address}}<br />{{customer.address2}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">City</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{customer.city}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">State</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{customer.state}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Country</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{customer.country}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-mid\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Invoice No.</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{invoice.number}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Invoice Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate invoice.date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Payment Type</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{invoice.payment_type}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-right\">\n        <img src=\"{{invoice.qr_code}}\" style=\"width:100px;height:100px\" />\n      </div>\n    </div>\n\n    <table class=\"items-table\">\n      <thead>\n        <tr>\n          <th class=\"center\">Sr.<br />No.</th>\n          <th class=\"left\">Product<br />Code</th>\n          <th class=\"left\">Product Description</th>\n          <th class=\"right\">Qty</th>\n          <th class=\"right\">Price</th>\n          <th class=\"right\">Value</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each invoice.items}}\n        <tr>\n          <td class=\"center sr\">{{inc @index}}</td>\n          <td>{{code}}</td>\n          <td>{{name}}</td>\n          <td class=\"num\">{{quantity}}</td>\n          <td class=\"num\">{{price}}</td>\n          <td class=\"num\">{{value}}</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n\n    <div class=\"bottom-section\">\n      <div class=\"bottom-left\">\n        <div class=\"meta-row\">  \n        </div>\n      </div>\n      <div class=\"summary\">\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Sub total</span>\n          <span class=\"s-val\">{{invoice.sub_total}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Discount</span>\n          <span class=\"s-val\">{{invoice.discount_amount}}</span>\n        </div>\n\n        {{#each tax_summary}}\n        <div class=\"tax-component-row\">\n          <span class=\"tcr-label\">{{name}}</span>\n          <span class=\"tcr-amount\">{{amount}}</span>\n        </div>\n        {{else}}\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Tax</span>\n          <span class=\"s-val\">{{invoice.tax_amount}}</span>\n        </div>\n        {{/each}}\n\n        <div class=\"summary-row total-row\">\n          <span class=\"s-label\">Grand Total</span>\n          <span class=\"s-val\">{{invoice.total}}</span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"footer-prepared\">\n      <span class=\"lbl\">Prepared By :</span>\n      <span class=\"val\">{{prepared_by}}</span>\n    </div>\n  </div>\n</div>\n</body>\n</html>',
