VALUES
  (
    9,
    1,
    'Default Template',
    'quotation',
    '<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Quotation</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;600&amp;display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --text: #111111;\n      --text-muted: #555555;\n      --border-heavy: 2px solid #111111;\n      --border-light: 1px solid #cccccc;\n      --border-dashed: 1px dashed #999999;\n      --accent: #1a1a1a;\n      --bg: #ffffff;\n      --row-alt: #f9f9f9;\n      --font-body: \'IBM Plex Sans\', sans-serif;\n      --font-mono: \'IBM Plex Mono\', monospace;\n    }\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    html, body {\n      width: 21cm;\n      margin: 0 auto;\n      font-family: var(--font-body);\n      color: var(--text);\n      background: #e8e8e8;\n      font-size: 11px;\n      line-height: 1.5;\n    }\n\n    .page-wrap {\n      width: 21cm;\n      min-height: 29.7cm;\n      height: auto;\n      overflow: visible;\n      background: var(--bg);\n      box-shadow: 0 4px 32px rgba(0, 0, 0, 0.18);\n    }\n\n    .doc {\n      width: 100%;\n      min-height: 29.7cm;\n      height: auto;\n      padding: 1cm;\n      overflow: visible;\n    }\n\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin-bottom: 28px;\n      padding-bottom: 24px;\n      border-bottom: var(--border-heavy);\n    }\n\n    .logo {\n      height: 140px;\n      object-fit: contain;\n    }\n\n    .company {\n      text-align: right;\n      max-width: 320px;\n    }\n\n    .company .name {\n      font-size: 22px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      margin-bottom: 6px;\n      color: var(--accent);\n    }\n\n    .company p {\n      font-size: 12px;\n      color: var(--text-muted);\n      line-height: 1.6;\n    }\n\n    .titlebar {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 28px;\n    }\n\n    .titlebar .line {\n      flex: 1;\n      height: 2px;\n      background: var(--text);\n    }\n\n    .titlebar .title {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n      white-space: nowrap;\n      color: var(--accent);\n    }\n\n    .info {\n      display: grid;\n      grid-template-columns: 1fr 1fr auto;\n      gap: 24px;\n      margin-bottom: 28px;\n      padding: 20px 24px;\n      border: var(--border-light);\n      background: #fafafa;\n    }\n\n    .kv-table {\n      display: table;\n      width: 100%;\n    }\n\n    .kv-row {\n      display: table-row;\n    }\n\n    .kv-label {\n      display: table-cell;\n      font-weight: 600;\n      font-size: 11px;\n      padding: 3px 10px 3px 0;\n      white-space: nowrap;\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .kv-sep {\n      display: table-cell;\n      padding: 3px 10px 3px 0;\n      color: var(--text-muted);\n      vertical-align: top;\n    }\n\n    .kv-val {\n      display: table-cell;\n      font-size: 11px;\n      vertical-align: top;\n      text-transform: uppercase;\n      color: var(--text);\n      font-weight: 500;\n    }\n\n    .info-right {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: flex-start;\n    }\n\n    .items-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 11px;\n      margin-bottom: 24px;\n    }\n\n    .items-table thead th {\n      border-top: var(--border-heavy);\n      border-bottom: var(--border-heavy);\n      padding: 10px 8px;\n      font-size: 10px;\n      font-weight: 700;\n      letter-spacing: 0.04em;\n      text-transform: uppercase;\n      color: var(--accent);\n      background: #fff;\n    }\n\n    .items-table thead th.left {\n      text-align: left;\n    }\n\n    .items-table thead th.right {\n      text-align: right;\n    }\n\n    .items-table thead th.center {\n      text-align: center;\n    }\n\n    .items-table tbody td {\n      padding: 9px 8px;\n      border-bottom: var(--border-dashed);\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .items-table tbody tr:nth-child(even) td {\n      background: var(--row-alt);\n    }\n\n    .items-table tbody tr:last-child td {\n      border-bottom: var(--border-heavy);\n    }\n\n    .items-table td.num {\n      text-align: right;\n      font-family: var(--font-mono);\n      font-size: 11px;\n    }\n\n    .items-table td.center {\n      text-align: center;\n    }\n\n    .items-table td.sr {\n      color: var(--text-muted);\n      font-weight: 600;\n    }\n\n    .bottom-section {\n      display: flex;\n      justify-content: space-between;\n      gap: 32px;\n      margin-bottom: 36px;\n    }\n\n    .bottom-left {\n      flex: 1;\n      font-size: 11px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n    }\n\n    .remarks .lbl,\n    .terms .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 4px;\n    }\n\n    .remarks .val,\n    .terms .val {\n      font-size: 11px;\n      color: var(--text);\n      line-height: 1.6;\n    }\n\n    .summary {\n      width: 260px;\n      flex-shrink: 0;\n      font-size: 11px;\n    }\n\n    .summary-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      padding: 8px 0;\n      border-bottom: var(--border-dashed);\n      gap: 12px;\n    }\n\n    .summary-row:last-child {\n      border-bottom: var(--border-heavy);\n      border-top: var(--border-heavy);\n      padding-top: 10px;\n      padding-bottom: 10px;\n      margin-top: 4px;\n    }\n\n    .s-label {\n      font-weight: 600;\n      color: var(--text);\n      font-size: 11px;\n      white-space: nowrap;\n    }\n\n    .s-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      font-size: 11px;\n      white-space: nowrap;\n    }\n\n    .summary-row:last-child .s-label,\n    .summary-row:last-child .s-val {\n      font-size: 13px;\n      font-weight: 700;\n    }\n\n    @media print {\n      @page {\n        size: A4;\n        margin: 0;\n      }\n\n      html, body {\n        background: #fff;\n        width: auto;\n        height: auto;\n        margin: 0;\n      }\n\n      .page-wrap {\n        box-shadow: none;\n        width: auto;\n        height: auto;\n        min-height: 0;\n        overflow: visible;\n        page-break-inside: avoid;\n      }\n\n      .doc {\n        width: auto;\n        height: auto;\n        min-height: 0;\n        padding: 0.5cm;\n        overflow: visible;\n        page-break-inside: avoid;\n      }\n\n      .info, .bottom-section {\n        page-break-inside: avoid;\n      }\n\n      * {\n        -webkit-print-color-adjust: exact;\n        print-color-adjust: exact;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"page-wrap\">\n    <div class=\"doc\">\n\n      <div class=\"header\">\n        <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\" />\n        <div class=\"company\">\n          <div class=\"name\">{{company.name}}</div>\n          <p>{{company.address}}</p>\n          <p>{{company.address2}}</p>\n          <p>Contact No: {{company.phone}}</p>\n          <p>Email: {{company.email}}</p>\n        </div>\n      </div>\n\n      <div class=\"titlebar\">\n        <div class=\"line\"></div>\n        <div class=\"title\">Quotation</div>\n        <div class=\"line\"></div>\n      </div>\n\n      <div class=\"info\">\n        <div class=\"info-left\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Customer Name</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{customer.name}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Address</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{customer.address}}<br />{{customer.address2}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">City</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{customer.city}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">State</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{customer.state}}</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"info-mid\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Quotation No.</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{quotation.number}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Quotation Date</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{formatDate quotation.date}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Valid Until</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{formatDate quotation.valid_until}}</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"info-right\">\n          <img src=\"{{quotation.qr_code}}\" style=\"width:100px;height:100px\" />\n        </div>\n      </div>\n\n      <table class=\"items-table\">\n        <thead>\n          <tr>\n            <th class=\"center\" style=\"width:40px\">Sr.<br />No.</th>\n            <th class=\"left\" style=\"width:100px\">Product<br />Code</th>\n            <th class=\"left\">Product Description</th>\n            <th class=\"right\" style=\"width:60px\">Qty</th>\n            <th class=\"right\" style=\"width:72px\">Price</th>\n            <th class=\"right\" style=\"width:90px\">Value</th>\n          </tr>\n        </thead>\n        <tbody>\n          {{#each quotation.items}}\n          <tr>\n            <td class=\"center sr\">{{inc @index}}</td>\n            <td>{{code}}</td>\n            <td>{{name}}</td>\n            <td class=\"num\">{{quantity}}</td>\n            <td class=\"num\">{{price}}</td>\n            <td class=\"num\">{{value}}</td>\n          </tr>\n          {{/each}}\n        </tbody>\n      </table>\n\n      <div class=\"bottom-section\">\n        <div class=\"bottom-left\">\n          <div class=\"remarks\">\n            <span class=\"lbl\">Remarks</span>\n            <span class=\"val\">{{quotation.remarks}}</span>\n          </div>\n          <div class=\"terms\">\n            <span class=\"lbl\">Terms and Conditions</span>\n            <span class=\"val\">{{quotation.terms_and_conditions}}</span>\n          </div>\n        </div>\n\n        <div class=\"summary\">\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Sub Total</span>\n            <span class=\"s-val\">{{quotation.sub_total}}</span>\n          </div>\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Total Discount</span>\n            <span class=\"s-val\">{{quotation.discount_total}}</span>\n          </div>\n          {{#each tax_summary}}\n          <div class=\"summary-row\">\n            <span class=\"s-label\">{{name}} </span>\n            <span class=\"s-val\">{{amount}}</span>\n          </div>\n          {{/each}}\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Total Tax</span>\n            <span class=\"s-val\">{{quotation.tax_total}}</span>\n          </div>\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Grand Total</span>\n            <span class=\"s-val\">{{quotation.grand_total}}</span>\n          </div>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</body>\n</html>',
