VALUES
  (
    16,
    1,
    'Salary Slip',
    'salary-slip',
    '<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Salary Slip</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;600&amp;display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --text: #111111;\n      --text-muted: #555555;\n      --border-heavy: 2px solid #111111;\n      --border-light: 1px solid #cccccc;\n      --border-dashed: 1px dashed #999999;\n      --accent: #1a1a1a;\n      --bg: #ffffff;\n      --row-alt: #f9f9f9;\n      --font-body: \'IBM Plex Sans\', sans-serif;\n      --font-mono: \'IBM Plex Mono\', monospace;\n    }\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    html, body {\n      width: 21cm;\n      height: 29.7cm;\n      margin: 0 auto;\n      font-family: var(--font-body);\n      color: var(--text);\n      background: #e8e8e8;\n      font-size: 11px;\n      line-height: 1.5;\n    }\n\n    .page-wrap {\n      width: 21cm;\n      height: 29.7cm;\n      overflow: hidden;\n      background: var(--bg);\n      box-shadow: 0 4px 32px rgba(0, 0, 0, 0.18);\n    }\n\n    .doc {\n      width: 100%;\n      height: 100%;\n      padding: 1cm;\n      overflow: hidden;\n    }\n\n    /* ── HEADER ── */\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin-bottom: 28px;\n      padding-bottom: 24px;\n      border-bottom: var(--border-heavy);\n    }\n\n    .logo {\n      height: 140px;\n      object-fit: contain;\n    }\n\n    .company {\n      text-align: right;\n      max-width: 320px;\n    }\n\n    .company .name {\n      font-size: 22px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      margin-bottom: 6px;\n      color: var(--accent);\n    }\n\n    .company p {\n      font-size: 12px;\n      color: var(--text-muted);\n      line-height: 1.6;\n    }\n\n    /* ── TITLE BAR ── */\n    .titlebar {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 28px;\n    }\n\n    .titlebar .line {\n      flex: 1;\n      height: 2px;\n      background: var(--text);\n    }\n\n    .titlebar .title {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n      white-space: nowrap;\n      color: var(--accent);\n    }\n\n    /* ── INFO GRID ── */\n    .info {\n      display: grid;\n      grid-template-columns: 1fr 1fr auto;\n      gap: 24px;\n      margin-bottom: 28px;\n      padding: 20px 24px;\n      border: var(--border-light);\n      background: #fafafa;\n    }\n\n    .kv-table {\n      display: table;\n      width: 100%;\n    }\n\n    .kv-row {\n      display: table-row;\n    }\n\n    .kv-label {\n      display: table-cell;\n      font-weight: 600;\n      font-size: 11px;\n      padding: 3px 10px 3px 0;\n      white-space: nowrap;\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .kv-sep {\n      display: table-cell;\n      padding: 3px 10px 3px 0;\n      color: var(--text-muted);\n      vertical-align: top;\n    }\n\n    .kv-val {\n      display: table-cell;\n      font-size: 11px;\n      vertical-align: top;\n      text-transform: uppercase;\n      color: var(--text);\n      font-weight: 500;\n    }\n\n    .info-right {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: flex-start;\n    }\n\n    .qr-box {\n      width: 80px;\n      height: 80px;\n    }\n\n    .qr-box img {\n      width: 100%;\n      height: 100%;\n    }\n\n    /* ── EARNINGS / DEDUCTIONS TABLE ── */\n    .pay-section {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 0;\n      border: var(--border-heavy);\n      margin-bottom: 24px;\n      font-size: 11px;\n    }\n\n    .pay-col {\n      display: flex;\n      flex-direction: column;\n    }\n\n    .pay-col:first-child {\n      border-right: var(--border-heavy);\n    }\n\n    .pay-col-header {\n      padding: 10px 12px;\n      font-size: 10px;\n      font-weight: 700;\n      letter-spacing: 0.04em;\n      text-transform: uppercase;\n      color: var(--accent);\n      border-bottom: var(--border-heavy);\n      display: flex;\n      justify-content: space-between;\n    }\n\n    .pay-row {\n      display: flex;\n      justify-content: space-between;\n      padding: 8px 12px;\n      border-bottom: var(--border-dashed);\n    }\n\n    .pay-row:nth-child(even) {\n      background: var(--row-alt);\n    }\n\n    .pay-row .pay-label {\n      color: var(--text);\n      font-weight: 500;\n    }\n\n    .pay-row .pay-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n    }\n\n    .pay-col-total {\n      display: flex;\n      justify-content: space-between;\n      padding: 10px 12px;\n      border-top: var(--border-heavy);\n      margin-top: auto;\n      font-weight: 700;\n      font-size: 11px;\n    }\n\n    .pay-col-total .pay-val {\n      font-family: var(--font-mono);\n    }\n\n    /* ── BOTTOM SECTION ── */\n    .bottom-section {\n      display: flex;\n      justify-content: space-between;\n      gap: 32px;\n      margin-bottom: 36px;\n    }\n\n    .bottom-left {\n      flex: 1;\n      font-size: 11px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n    }\n\n    .meta-row {\n      display: flex;\n      gap: 40px;\n      flex-wrap: wrap;\n    }\n\n    .meta-item .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 2px;\n    }\n\n    .meta-item .val {\n      font-size: 11px;\n      font-weight: 600;\n    }\n\n    .amount-words .lbl,\n    .remarks .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 4px;\n    }\n\n    .amount-words .val {\n      font-size: 11px;\n      font-weight: 600;\n      text-transform: uppercase;\n      color: var(--accent);\n      font-family: var(--font-mono);\n    }\n\n    .remarks .val {\n      font-size: 11px;\n      color: var(--text);\n      line-height: 1.6;\n    }\n\n    /* ── NET PAY SUMMARY ── */\n    .summary {\n      width: 260px;\n      flex-shrink: 0;\n      font-size: 11px;\n    }\n\n    .summary-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      padding: 8px 0;\n      border-bottom: var(--border-dashed);\n      gap: 12px;\n    }\n\n    .summary-row:last-child {\n      border-bottom: var(--border-heavy);\n      padding-top: 10px;\n      padding-bottom: 10px;\n      border-top: var(--border-heavy);\n      margin-top: 4px;\n    }\n\n    .s-label {\n      font-weight: 600;\n      color: var(--text);\n      font-size: 11px;\n    }\n\n    .s-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      font-size: 11px;\n      white-space: nowrap;\n    }\n\n    .summary-row:last-child .s-label,\n    .summary-row:last-child .s-val {\n      font-size: 13px;\n      font-weight: 700;\n    }\n\n    /* ── FOOTER ── */\n    .footer-prepared {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding-top: 16px;\n      border-top: var(--border-heavy);\n      font-size: 11px;\n    }\n\n    .footer-prepared .lbl {\n      font-weight: 700;\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: var(--text-muted);\n    }\n\n    .footer-prepared .val {\n      font-weight: 600;\n    }\n\n    .footer-note {\n      margin-left: auto;\n      font-size: 10px;\n      color: var(--text-muted);\n      font-style: italic;\n    }\n\n    /* ── PRINT ── */\n    @media print {\n      @page {\n        size: 21cm 29.7cm;\n        margin: 0;\n      }\n\n      html, body {\n        background: #fff;\n        width: 21cm;\n        height: 29.7cm;\n      }\n\n      .page-wrap {\n        box-shadow: none;\n        width: 21cm;\n        height: 29.7cm;\n      }\n\n      * {\n        -webkit-print-color-adjust: exact;\n        print-color-adjust: exact;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"page-wrap\">\n    <div class=\"doc\">\n\n      <div class=\"header\">\n        <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\" />\n        <div class=\"company\">\n          <div class=\"name\">{{company.name}}</div>\n          <p>{{company.address}}</p>\n          <p>{{company.address2}}</p>\n          <p>Contact No: {{company.phone}}</p>\n          <p>Email: {{company.email}}</p>\n        </div>\n      </div>\n\n      <div class=\"titlebar\">\n        <div class=\"line\"></div>\n        <div class=\"title\">Salary Slip</div>\n        <div class=\"line\"></div>\n      </div>\n\n      <div class=\"info\">\n        <div class=\"info-left\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Employee Name</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.name}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Employee ID</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.id}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Department</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.department}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Designation</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.designation}}</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"info-mid\">\n          <div class=\"kv-table\">\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Pay Period</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{salary_slip.pay_period}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Pay Date</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{formatDate salary_slip.pay_date}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Bank Account</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.bank_account}}</div>\n            </div>\n            <div class=\"kv-row\">\n              <div class=\"kv-label\">Bank Name</div>\n              <div class=\"kv-sep\">:</div>\n              <div class=\"kv-val\">{{employee.bank_name}}</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"info-right\">\n          <div class=\"qr-box\"><img src=\"{{salary_slip.qr_code}}\" alt=\"QR\" /></div>\n        </div>\n      </div>\n\n      <div class=\"pay-section\">\n\n        <div class=\"pay-col\">\n          <div class=\"pay-col-header\">\n            <span>Earnings</span>\n            <span>Amount</span>\n          </div>\n          {{#each salary_slip.earnings}}\n          <div class=\"pay-row\">\n            <span class=\"pay-label\">{{name}}</span>\n            <span class=\"pay-val\">{{amount}}</span>\n          </div>\n          {{/each}}\n          <div class=\"pay-col-total\">\n            <span>Total Earnings</span>\n            <span class=\"pay-val\">{{salary_slip.total_earnings}}</span>\n          </div>\n        </div>\n\n        <div class=\"pay-col\">\n          <div class=\"pay-col-header\">\n            <span>Deductions</span>\n            <span>Amount</span>\n          </div>\n          {{#each salary_slip.deductions}}\n          <div class=\"pay-row\">\n            <span class=\"pay-label\">{{name}}</span>\n            <span class=\"pay-val\">{{amount}}</span>\n          </div>\n          {{/each}}\n          <div class=\"pay-col-total\">\n            <span>Total Deductions</span>\n            <span class=\"pay-val\">{{salary_slip.total_deductions}}</span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"bottom-section\">\n        <div class=\"bottom-left\">\n          <div class=\"meta-row\">\n            <div class=\"meta-item\">\n              <span class=\"lbl\">Leave Taken</span>\n              <span class=\"val\">{{salary_slip.leave_taken}}</span>\n            </div>\n          </div>\n          <div class=\"amount-words\">\n            <span class=\"lbl\">Net Pay in Words</span>\n            <span class=\"val\">{{salary_slip.net_pay_in_words}}</span>\n          </div>\n          <div class=\"remarks\">\n            <span class=\"lbl\">Remarks</span>\n            <span class=\"val\">{{salary_slip.remarks}}</span>\n          </div>\n        </div>\n\n        <div class=\"summary\">\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Gross Earnings</span>\n            <span class=\"s-val\">{{salary_slip.total_earnings}}</span>\n          </div>\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Total Deductions</span>\n            <span class=\"s-val\">{{salary_slip.total_deductions}}</span>\n          </div>\n          <div class=\"summary-row\">\n            <span class=\"s-label\">Net Pay</span>\n            <span class=\"s-val\">{{salary_slip.net_pay}}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</body>\n</html>',
