    'Purchase Order',
    'purchase-order',
    '<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Purchase Order</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;600&amp;display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --text: #111111;\n      --text-muted: #555555;\n      --border-heavy: 2px solid #111111;\n      --border-light: 1px solid #cccccc;\n      --border-dashed: 1px dashed #999999;\n      --accent: #1a1a1a;\n      --bg: #ffffff;\n      --row-alt: #f9f9f9;\n      --font-body: \'IBM Plex Sans\', sans-serif;\n      --font-mono: \'IBM Plex Mono\', monospace;\n    }\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    html, body {\n      width: 21cm;\n      height: 29.7cm;\n      margin: 0 auto;\n      font-family: var(--font-body);\n      color: var(--text);\n      background: #e8e8e8;\n      font-size: 22px;\n      line-height: 1.5;\n    }\n\n    .page-wrap {\n      width: 21cm;\n      height: 29.7cm;\n      overflow: hidden;\n      background: var(--bg);\n      box-shadow: 0 4px 32px rgba(0,0,0,0.18);\n    }\n\n    .doc {\n      width: 21cm;\n      height: 29.7cm;\n      padding: 10px 10px 10px;\n      overflow: hidden;\n    }\n\n    /* ── HEADER ── */\n    .header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin-bottom: 28px;\n      padding-bottom: 24px;\n      border-bottom: var(--border-heavy);\n    }\n\n    .logo {\n      height: 140px;\n      object-fit: contain;\n    }\n\n    .company {\n      text-align: right;\n      max-width: 320px;\n    }\n\n    .company .name {\n      font-size: 32px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      margin-bottom: 6px;\n      color: var(--accent);\n    }\n\n    .company p {\n      font-size: 17px;\n      color: var(--text-muted);\n      line-height: 1.6;\n    }\n\n    /* ── TITLE BAR ── */\n    .titlebar {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 28px;\n    }\n\n    .titlebar .line {\n      flex: 1;\n      height: 2px;\n      background: var(--text);\n    }\n\n    .titlebar .title {\n      font-size: 20px;\n      font-weight: 700;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n      white-space: nowrap;\n      color: var(--accent);\n    }\n\n    /* ── INFO GRID ── */\n    .info {\n      display: grid;\n      grid-template-columns: 1fr 1fr auto;\n      gap: 24px;\n      margin-bottom: 28px;\n      padding: 20px 24px;\n      border: var(--border-light);\n      background: #fafafa;\n    }\n\n    .kv-table {\n      display: table;\n      width: 100%;\n    }\n\n    .kv-row {\n      display: table-row;\n    }\n\n    .kv-label {\n      display: table-cell;\n      font-weight: 600;\n      font-size: 15px;\n      padding: 3px 10px 3px 0;\n      white-space: nowrap;\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .kv-sep {\n      display: table-cell;\n      padding: 3px 10px 3px 0;\n      color: var(--text-muted);\n      vertical-align: top;\n    }\n\n    .kv-val {\n      display: table-cell;\n      font-size: 15px;\n      vertical-align: top;\n      text-transform: uppercase;\n      color: var(--text);\n      font-weight: 500;\n    }\n\n    .info-right {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: flex-start;\n    }\n\n    /* ── TABLE ── */\n    .items-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 15px;\n      margin-bottom: 24px;\n    }\n\n    .items-table thead th {\n      border-top: var(--border-heavy);\n      border-bottom: var(--border-heavy);\n      padding: 10px 8px;\n      font-size: 14px;\n      font-weight: 700;\n      letter-spacing: 0.04em;\n      text-transform: uppercase;\n      color: var(--accent);\n      background: #fff;\n    }\n\n    .items-table thead th.left { text-align: left; }\n    .items-table thead th.right { text-align: right; }\n    .items-table thead th.center { text-align: center; }\n\n    .items-table tbody td {\n      padding: 9px 8px;\n      border-bottom: var(--border-dashed);\n      vertical-align: top;\n      color: var(--text);\n    }\n\n    .items-table tbody tr:nth-child(even) td { background: var(--row-alt); }\n    .items-table tbody tr:last-child td { border-bottom: var(--border-heavy); }\n\n    .items-table td.num {\n      text-align: right;\n      font-family: var(--font-mono);\n      font-size: 15px;\n    }\n\n    .items-table td.center { text-align: center; }\n    .items-table td.sr { color: var(--text-muted); font-weight: 600; }\n\n    /* ── BOTTOM SECTION ── */\n    .bottom-section {\n      display: flex;\n      justify-content: space-between;\n      gap: 32px;\n      margin-bottom: 36px;\n    }\n\n    .bottom-left {\n      flex: 1;\n      font-size: 15px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n    }\n\n    .meta-row {\n      display: flex;\n      gap: 40px;\n    }\n\n    .meta-item .lbl {\n      font-weight: 700;\n      font-size: 13px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 2px;\n    }\n\n    .meta-item .val {\n      font-size: 15px;\n      font-weight: 600;\n    }\n\n    .amount-words .lbl,\n    .remarks .lbl,\n    .terms .lbl {\n      font-weight: 700;\n      font-size: 13px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 4px;\n    }\n\n    .amount-words .val {\n      font-size: 14px;\n      font-weight: 600;\n      text-transform: uppercase;\n      color: var(--accent);\n      font-family: var(--font-mono);\n    }\n\n    .remarks .val,\n    .terms .val {\n      font-size: 14px;\n      color: var(--text);\n      line-height: 1.6;\n    }\n\n    /* ── SUMMARY ── */\n    .summary {\n      width: 260px;\n      flex-shrink: 0;\n      font-size: 15px;\n    }\n\n    .summary-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      padding: 8px 0;\n      border-bottom: var(--border-dashed);\n      gap: 12px;\n    }\n\n    .summary-row:last-child {\n      border-bottom: var(--border-heavy);\n      padding-top: 10px;\n      padding-bottom: 10px;\n      border-top: var(--border-heavy);\n      margin-top: 4px;\n    }\n\n    .s-label {\n      font-weight: 600;\n      color: var(--text);\n      font-size: 15px;\n    }\n\n    .s-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      font-size: 15px;\n      white-space: nowrap;\n    }\n\n    .summary-row:last-child .s-label,\n    .summary-row:last-child .s-val {\n      font-size: 18px;\n      font-weight: 700;\n    }\n\n    /* ── APPROVAL SECTION ── */\n    .approval-section {\n      display: flex;\n      gap: 32px;\n      margin-bottom: 24px;\n    }\n\n    .approval-box {\n      flex: 1;\n      border-top: var(--border-heavy);\n      padding-top: 8px;\n    }\n\n    .approval-box .lbl {\n      font-weight: 700;\n      font-size: 13px;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: var(--text-muted);\n      display: block;\n      margin-bottom: 4px;\n    }\n\n    .approval-box .val {\n      font-size: 15px;\n      font-weight: 600;\n    }\n\n    .sig-line {\n      margin-top: 32px;\n      border-top: 1px solid #aaaaaa;\n      padding-top: 6px;\n      font-size: 13px;\n      color: var(--text-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n\n    /* ── FOOTER ── */\n    .footer-prepared {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding-top: 16px;\n      border-top: var(--border-heavy);\n      font-size: 15px;\n    }\n\n    .footer-prepared .lbl {\n      font-weight: 700;\n      font-size: 13px;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: var(--text-muted);\n    }\n\n    .footer-prepared .val {\n      font-weight: 600;\n    }\n\n    /* ── PRINT ── */\n    @media print {\n      @page { size: 21cm 29.7cm; margin: 0; }\n      html, body { background: #fff; width: 21cm; height: 29.7cm; }\n      .page-wrap { box-shadow: none; width: 21cm; height: 29.7cm; }\n      * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n    }\n  </style>\n</head>\n<body>\n<div class=\"page-wrap\">\n  <div class=\"doc\">\n\n    \n    <div class=\"header\">\n      <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\" />\n      <div class=\"company\">\n        <div class=\"name\">{{company.name}}</div>\n        <p>{{company.address}}</p>\n        <p>{{company.address2}}</p>\n        <p>Contact No: {{company.phone}}</p>\n        <p>Email: {{company.email}}</p>\n      </div>\n    </div>\n\n    \n    <div class=\"titlebar\">\n      <div class=\"line\"></div>\n      <div class=\"title\">Purchase Order</div>\n      <div class=\"line\"></div>\n    </div>\n\n    \n    <div class=\"info\">\n      <div class=\"info-left\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Vendor Name</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.name}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Address</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.address}}<br />{{vendor.address2}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">City</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.city}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">State</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.state}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Country</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.country}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-mid\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">PO Number</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_order.number}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">PO Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate purchase_order.date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Delivery Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate purchase_order.delivery_date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Payment Term</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_order.payment_terms}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Delivery To</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_order.delivery_location}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-right\">\n        <img src=\"{{qr_code}}\" style=\"width:100px;height:100px\" />\n      </div>\n    </div>\n\n    \n    <table class=\"items-table\">\n      <thead>\n        <tr>\n          <th class=\"center\" style=\"width:40px\">Sr.<br />No.</th>\n          <th class=\"left\" style=\"width:100px\">Product<br />Code</th>\n          <th class=\"left\">Product Description</th>\n          <th class=\"right\" style=\"width:52px\">Qty</th>\n          <th class=\"right\" style=\"width:60px\">Unit</th>\n          <th class=\"right\" style=\"width:72px\">Unit Price</th>\n          <th class=\"right\" style=\"width:72px\">Discount</th>\n          <th class=\"right\" style=\"width:60px\">Tax</th>\n          <th class=\"right\" style=\"width:80px\">Value</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each purchase_order.items}}\n        <tr>\n          <td class=\"center sr\">{{inc @index}}</td>\n          <td>{{code}}</td>\n          <td>{{name}}</td>\n          <td class=\"num\">{{quantity}}</td>\n          <td class=\"num\">{{unit}}</td>\n          <td class=\"num\">{{unit_price}}</td>\n          <td class=\"num\">{{discount}}</td>\n          <td class=\"num\">{{tax}}</td>\n          <td class=\"num\">{{amount}}</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n\n    \n    <div class=\"bottom-section\">\n      <div class=\"bottom-left\">\n        <div class=\"meta-row\">\n          <div class=\"meta-item\">\n            <span class=\"lbl\">Item Count</span>\n            <span class=\"val\">{{purchase_order.item_count}}</span>\n          </div>\n          <div class=\"meta-item\">\n            <span class=\"lbl\">Total Quantity</span>\n            <span class=\"val\">{{purchase_order.total_quantity}}</span>\n          </div>\n        </div>\n        <div class=\"amount-words\">\n          <span class=\"lbl\">Amount in Words</span>\n          <span class=\"val\">{{purchase_order.amount_in_words}}</span>\n        </div>\n        <div class=\"remarks\">\n          <span class=\"lbl\">Remarks</span>\n          <span class=\"val\">{{purchase_order.remarks}}</span>\n        </div>\n        <div class=\"terms\">\n          <span class=\"lbl\">Terms and Conditions</span>\n          <span class=\"val\">{{purchase_order.terms_and_conditions}}</span>\n        </div>\n      </div>\n\n      <div class=\"summary\">\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Sub Total</span>\n          <span class=\"s-val\">{{purchase_order.sub_total}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Discount</span>\n          <span class=\"s-val\">{{purchase_order.discount_amount}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Tax</span>\n          <span class=\"s-val\">{{purchase_order.tax_amount}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Net Order Value</span>\n          <span class=\"s-val\">{{purchase_order.total}}</span>\n        </div>\n      </div>\n    </div>\n\n    \n    <div class=\"approval-section\">\n      <div class=\"approval-box\">\n        <span class=\"lbl\">Prepared By</span>\n        <span class=\"val\">{{prepared_by}}</span>\n        <div class=\"sig-line\">Signature</div>\n      </div>\n      <div class=\"approval-box\">\n        <span class=\"lbl\">Approved By</span>\n        <span class=\"val\">{{approved_by}}</span>\n        <div class=\"sig-line\">Signature</div>\n      </div>\n      <div class=\"approval-box\">\n        <span class=\"lbl\">Vendor Acknowledgement</span>\n        <span class=\"val\"> </span>\n        <div class=\"sig-line\">Signature &amp; Stamp</div>\n      </div>\n    </div>\n\n  </div>\n</div>\n</body>\n</html>',
