VALUES
  (
    27,
    1,
    'Purchase Bill',
    'purchase-bill',
    '<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Purchase Bill</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;600&amp;display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --text: #111111;\n      --text-muted: #555555;\n      --border-heavy: 2px solid #111111;\n      --border-light: 1px solid #cccccc;\n      --border-dashed: 1px dashed #999999;\n      --accent: #1a1a1a;\n      --bg: #ffffff;\n      --row-alt: #f9f9f9;\n      --font-body: \'IBM Plex Sans\', sans-serif;\n      --font-mono: \'IBM Plex Mono\', monospace;\n    }\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    html, body {\n      width: 21cm; height: 29.7cm; margin: 0 auto;\n      font-family: var(--font-body); color: var(--text);\n      background: #e8e8e8; font-size: 22px; line-height: 1.5;\n    }\n    .page-wrap { width: 21cm; height: 29.7cm; overflow: hidden; background: var(--bg); box-shadow: 0 4px 32px rgba(0,0,0,0.18); }\n    .doc { width: 21cm; height: 29.7cm; padding: 10px; overflow: hidden; }\n\n    /* HEADER */\n    .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 28px; padding-bottom: 24px; border-bottom: var(--border-heavy); }\n    .logo { height: 140px; object-fit: contain; }\n    .company { text-align: right; max-width: 320px; }\n    .company .name { font-size: 32px; font-weight: 700; letter-spacing: -0.02em; margin-bottom: 6px; color: var(--accent); }\n    .company p { font-size: 17px; color: var(--text-muted); line-height: 1.6; }\n\n    /* TITLE BAR */\n    .titlebar { display: flex; align-items: center; gap: 16px; margin-bottom: 28px; }\n    .titlebar .line { flex: 1; height: 2px; background: var(--text); }\n    .titlebar .title { font-size: 20px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; white-space: nowrap; color: var(--accent); }\n\n    /* STATUS BADGE */\n    .status-badge { display: inline-block; padding: 3px 12px; border: var(--border-heavy); font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }\n\n    /* INFO GRID */\n    .info { display: grid; grid-template-columns: 1fr 1fr auto; gap: 24px; margin-bottom: 28px; padding: 20px 24px; border: var(--border-light); background: #fafafa; }\n    .kv-table { display: table; width: 100%; }\n    .kv-row { display: table-row; }\n    .kv-label { display: table-cell; font-weight: 600; font-size: 15px; padding: 3px 10px 3px 0; white-space: nowrap; vertical-align: top; color: var(--text); }\n    .kv-sep { display: table-cell; padding: 3px 10px 3px 0; color: var(--text-muted); vertical-align: top; }\n    .kv-val { display: table-cell; font-size: 15px; vertical-align: top; text-transform: uppercase; color: var(--text); font-weight: 500; }\n    .info-right { display: flex; flex-direction: column; align-items: center; justify-content: flex-start; gap: 10px; }\n\n    /* TABLE */\n    .items-table { width: 100%; border-collapse: collapse; font-size: 15px; margin-bottom: 24px; }\n    .items-table thead th { border-top: var(--border-heavy); border-bottom: var(--border-heavy); padding: 10px 8px; font-size: 14px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--accent); background: #fff; }\n    .items-table thead th.left { text-align: left; }\n    .items-table thead th.right { text-align: right; }\n    .items-table thead th.center { text-align: center; }\n    .items-table tbody td { padding: 9px 8px; border-bottom: var(--border-dashed); vertical-align: top; color: var(--text); }\n    .items-table tbody tr:nth-child(even) td { background: var(--row-alt); }\n    .items-table tbody tr:last-child td { border-bottom: var(--border-heavy); }\n    .items-table td.num { text-align: right; font-family: var(--font-mono); font-size: 15px; }\n    .items-table td.center { text-align: center; }\n    .items-table td.sr { color: var(--text-muted); font-weight: 600; }\n\n    /* BOTTOM SECTION */\n    .bottom-section { display: flex; justify-content: space-between; gap: 32px; margin-bottom: 20px; }\n    .bottom-left { flex: 1; font-size: 15px; display: flex; flex-direction: column; gap: 14px; }\n    .meta-row { display: flex; gap: 40px; }\n    .meta-item .lbl { font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-muted); display: block; margin-bottom: 2px; }\n    .meta-item .val { font-size: 15px; font-weight: 600; }\n    .amount-words .lbl, .remarks .lbl, .terms .lbl { font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-muted); display: block; margin-bottom: 4px; }\n    .amount-words .val { font-size: 14px; font-weight: 600; text-transform: uppercase; color: var(--accent); font-family: var(--font-mono); }\n    .remarks .val, .terms .val { font-size: 14px; color: var(--text); line-height: 1.6; }\n\n    /* SUMMARY */\n    .summary { width: 260px; flex-shrink: 0; font-size: 15px; }\n    .summary-row { display: flex; justify-content: space-between; align-items: flex-start; padding: 8px 0; border-bottom: var(--border-dashed); gap: 12px; }\n    .summary-row:last-child { border-bottom: var(--border-heavy); padding-top: 10px; padding-bottom: 10px; border-top: var(--border-heavy); margin-top: 4px; }\n    .s-label { font-weight: 600; color: var(--text); font-size: 15px; }\n    .s-val { font-family: var(--font-mono); font-weight: 600; font-size: 15px; white-space: nowrap; }\n    .summary-row:last-child .s-label, .summary-row:last-child .s-val { font-size: 18px; font-weight: 700; }\n\n    /* PAYMENT STATUS PANEL */\n    .payment-panel { border: var(--border-light); background: #fafafa; padding: 14px 18px; margin-bottom: 20px; }\n    .payment-panel .panel-title { font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); display: block; margin-bottom: 10px; }\n    .payment-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }\n    .p-item .p-lbl { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-muted); display: block; margin-bottom: 2px; }\n    .p-item .p-val { font-size: 15px; font-weight: 600; font-family: var(--font-mono); }\n\n    /* SIGNATURE */\n    .sig-section { display: flex; gap: 32px; padding-top: 16px; border-top: var(--border-heavy); }\n    .sig-box { flex: 1; }\n    .sig-box .lbl { font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); display: block; margin-bottom: 4px; }\n    .sig-box .val { font-size: 15px; font-weight: 600; }\n    .sig-line { margin-top: 28px; border-top: 1px solid #aaaaaa; padding-top: 6px; font-size: 13px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; }\n\n    @media print {\n      @page { size: 21cm 29.7cm; margin: 0; }\n      html, body { background: #fff; width: 21cm; height: 29.7cm; }\n      .page-wrap { box-shadow: none; }\n      * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n    }\n  </style>\n</head>\n<body>\n<div class=\"page-wrap\">\n  <div class=\"doc\">\n\n    \n    <div class=\"header\">\n      <img class=\"logo\" src=\"{{company.logo}}\" alt=\"Logo\" />\n      <div class=\"company\">\n        <div class=\"name\">{{company.name}}</div>\n        <p>{{company.address}}</p>\n        <p>{{company.address2}}</p>\n        <p>Contact No: {{company.phone}}</p>\n        <p>Email: {{company.email}}</p>\n      </div>\n    </div>\n\n    \n    <div class=\"titlebar\">\n      <div class=\"line\"></div>\n      <div class=\"title\">Purchase Bill</div>\n      <div class=\"line\"></div>\n    </div>\n\n    \n    <div class=\"info\">\n      <div class=\"info-left\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Vendor Name</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.name}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Address</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.address}}&lt;<br />{{vendor.address2}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">City</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.city}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">State</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.state}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Country</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{vendor.country}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-mid\">\n        <div class=\"kv-table\">\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Bill Number</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_bill.number}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Bill Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate purchase_bill.date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Vendor Invoice No.</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_bill.vendor_invoice_no}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Invoice Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate purchase_bill.vendor_invoice_date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">Due Date</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{formatDate purchase_bill.due_date}}</div>\n          </div>\n          <div class=\"kv-row\">\n            <div class=\"kv-label\">PO Reference</div>\n            <div class=\"kv-sep\">:</div>\n            <div class=\"kv-val\">{{purchase_bill.po_reference}}</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"info-right\">\n        <img src=\"{{qr_code}}\" style=\"width:100px;height:100px\" />\n        <div class=\"status-badge\">{{purchase_bill.status}}</div>\n      </div>\n    </div>\n\n    \n    <table class=\"items-table\">\n      <thead>\n        <tr>\n          <th class=\"center\" style=\"width:40px\">Sr.<br />No.</th>\n          <th class=\"left\" style=\"width:100px\">Product<br />Code</th>\n          <th class=\"left\">Product Description</th>\n          <th class=\"right\" style=\"width:52px\">Qty</th>\n          <th class=\"right\" style=\"width:60px\">Unit</th>\n          <th class=\"right\" style=\"width:72px\">Rate</th>\n          <th class=\"right\" style=\"width:72px\">Discount</th>\n          <th class=\"right\" style=\"width:80px\">Value</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{#each purchase_bill.items}}\n        <tr>\n          <td class=\"center sr\">{{inc @index}}</td>\n          <td>{{code}}</td>\n          <td>{{name}}</td>\n          <td class=\"num\">{{quantity}}</td>\n          <td class=\"num\">{{unit}}</td>\n          <td class=\"num\">{{rate}}</td>\n          <td class=\"num\">{{discount}}</td>\n          <td class=\"num\">{{value}}</td>\n        </tr>\n        {{/each}}\n      </tbody>\n    </table>\n\n    \n    <div class=\"bottom-section\">\n      <div class=\"bottom-left\">\n        <div class=\"meta-row\">\n          <div class=\"meta-item\">\n            <span class=\"lbl\">Item Count</span>\n            <span class=\"val\">{{purchase_bill.item_count}}</span>\n          </div>\n          <div class=\"meta-item\">\n            <span class=\"lbl\">Total Quantity</span>\n            <span class=\"val\">{{purchase_bill.total_quantity}}</span>\n          </div>\n        </div>\n        <div class=\"amount-words\">\n          <span class=\"lbl\">Amount in Words</span>\n          <span class=\"val\">{{purchase_bill.amount_in_words}}</span>\n        </div>\n        <div class=\"remarks\">\n          <span class=\"lbl\">Remarks</span>\n          <span class=\"val\">{{purchase_bill.remarks}}</span>\n        </div>\n        <div class=\"terms\">\n          <span class=\"lbl\">Terms and Conditions</span>\n          <span class=\"val\">{{purchase_bill.terms_and_conditions}}</span>\n        </div>\n      </div>\n\n      <div class=\"summary\">\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Sub Total</span>\n          <span class=\"s-val\">{{purchase_bill.sub_total}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Discount</span>\n          <span class=\"s-val\">{{purchase_bill.discount_amount}}</span>\n        </div>\n        {{#each purchase_bill.tax_components}}\n        <div class=\"summary-row\">\n          <span class=\"s-label\">{{name}}</span>\n          <span class=\"s-val\">{{amount}}</span>\n        </div>\n        {{/each}}\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Additional Charges</span>\n          <span class=\"s-val\">{{purchase_bill.additional_charges}}</span>\n        </div>\n        <div class=\"summary-row\">\n          <span class=\"s-label\">Net Bill Amount</span>\n          <span class=\"s-val\">{{purchase_bill.total}}</span>\n        </div>\n      </div>\n    </div>\n\n    \n    <div class=\"payment-panel\">\n      <span class=\"panel-title\">Payment Status</span>\n      <div class=\"payment-grid\">\n        <div class=\"p-item\">\n          <span class=\"p-lbl\">Payment Mode</span>\n          <span class=\"p-val\">{{purchase_bill.payment_mode}}</span>\n        </div>\n        <div class=\"p-item\">\n          <span class=\"p-lbl\">Amount Paid</span>\n          <span class=\"p-val\">{{purchase_bill.amount_paid}}</span>\n        </div>\n        <div class=\"p-item\">\n          <span class=\"p-lbl\">Balance Due</span>\n          <span class=\"p-val\">{{purchase_bill.balance_due}}</span>\n        </div>\n        <div class=\"p-item\">\n          <span class=\"p-lbl\">Payment Date</span>\n          <span class=\"p-val\">{{formatDate purchase_bill.payment_date}}</span>\n        </div>\n        <div class=\"p-item\">\n          <span class=\"p-lbl\">Reference No.</span>\n          <span class=\"p-val\">{{purchase_bill.payment_reference}}</span>\n        </div>\n      </div>\n    </div>\n\n    \n    <div class=\"sig-section\">\n      <div class=\"sig-box\">\n        <span class=\"lbl\">Prepared By</span>\n        <span class=\"val\">{{prepared_by}}</span>\n        <div class=\"sig-line\">Signature</div>\n      </div>\n      <div class=\"sig-box\">\n        <span class=\"lbl\">Verified By</span>\n        <span class=\"val\">{{verified_by}}</span>\n        <div class=\"sig-line\">Signature</div>\n      </div>\n      <div class=\"sig-box\">\n        <span class=\"lbl\">Approved By</span>\n        <span class=\"val\">{{approved_by}}</span>\n        <div class=\"sig-line\">Signature</div>\n      </div>\n    </div>\n\n  </div>\n</div>\n</body>\n</html>',
    1,
    NULL,
    '2026-04-08 23:11:41',
    '2026-06-02 17:14:09',
    '',
    'Seriana Mart',
